package com.dy.artisan3d.data.repositoryimport com.dy.artisan3d.data.model.CategoryResponseimport com.dy.artisan3d.domain.model.Categoryimport com.dy.artisan3d.domain.repository.CategoryRepositoryimport com.dy.artisan3d.util.Constants.BASE_URLimport com.dy.artisan3d.util.Constants.FILE_URLimport com.dy.artisan3d.util.safeApiCallimport io.ktor.client.HttpClientimport io.ktor.client.call.bodyimport io.ktor.client.request.getclass CategoryRepositoryImpl(    private val httpClient: HttpClient) : CategoryRepository {    override suspend fun getCategories(lang: String): Result<List<Category>> {        val result: Result<CategoryResponse> = safeApiCall {            httpClient.get(BASE_URL + "categories").body<CategoryResponse>()        }        return result.map { response ->            response.data.map { dto ->                Category(                    id = dto.id,                    name = dto.translations[lang]?.name ?: dto.translations["uz"]?.name ?: "",                    iconUrl = FILE_URL + dto.icon                )            }        }    }}